using System.Collections.Generic;                     // List
using UnityEngine;                                    // core Unity API
using UnityEngine.InputSystem;                        // keyboard (new Input System)

// Physics of the robot fish (Assets/AUV/Prefabs/RobotFish.prefab), built from its CAD model.
// Every number used here comes from Docs/RobotFish_CAD_Report.md (generated by Tools/cad_analysis)
// and the assumptions are listed in Docs/RobotFish_Assumptions.md.
//
// Local axes of the robot (same as the sensors expect): forward = −X, up = +Y, right (starboard) = +Z.
// The origin is the center of the hull tube.
//
// Each physics step (FixedUpdate):
//   1. actuators: keyboard or external commands → tail oscillator and servo, moving mass position;
//   2. mass properties: structure + moving mass (its position changes the center of mass and the inertia);
//   3. buoyancy: computed over points that fill the real displaced volume (hull, dome, parts outside);
//   4. hull drag: quadratic, small along the hull, large across it ("strip theory": the hull is cut into
//      slices, each one sees its own water velocity, so the drag also resists rotations);
//   5. fins: the flapping tail fin gives the propulsion and the steering (section 6), the dorsal fin (fixed)
//      produces a force normal to its plate.
//
// Two propulsion models (field `propulsion`):
//   - TailFlapping (default): the servo swings the tail fin as bias + amplitude·sin(2π·frequency·t); the
//     forces of the water on the moving fin push the robot forward and turn it (section 6);
//   - SimpleThrust (tests): the fin is a rudder held at a fixed angle and a forward force replaces the
//     flapping (the model used before the flapping tail).
//
// Not modeled (see Docs/RobotFish_Model.md): sideways/vertical added mass of the hull in translation,
// waves and currents.
[RequireComponent(typeof(Rigidbody))]
public class RobotFishPhysics : MonoBehaviour
{
    const float WaterDensity = 1000f;                 // fresh water [kg/m³]

    // ------------------------------------------------------------------ environment
    [Header("Environment")]
    [Tooltip("Basin providing the water surface height (empty = search the scene).")]
    public TestBasin basin;
    [Tooltip("Water surface height used when there is no basin [m, world Y].")]
    public float fallbackWaterLevel = 0f;

    // ------------------------------------------------------------------ mass properties
    // The robot carries no ballast: its mass is the structure plus the moving mass. Its buoyancy is therefore a
    // result, not a setting. Two models for how the structure mass is distributed (field `massModel`):
    //   - Simplified (default): the components only matter as a total mass. The structure is balanced like a
    //     well-trimmed robot: its center of mass is right under the center of buoyancy (B) with the moving mass at
    //     the tube center, `centerOfMassBelowBuoyancy` (BG) below it, and its inertia is that of a uniform cylinder
    //     of the hull size. On the real robot this balance is reached by placing the battery and the other
    //     components; BG is mainly set by how low the battery is mounted.
    //   - Cad: center of mass and inertia from the CAD parts (Docs/RobotFish_CAD_Report.md).
    public enum MassModel { Simplified, Cad }

    [Header("Structure (everything except the moving mass)")]
    [Tooltip("Mass of the structure: hull, electronics, battery, servos, fins [kg] (team estimate: about 4 kg).")]
    public float structureMass = 4.000f;
    [Tooltip("Simplified: balanced structure, center of mass under the center of buoyancy (computed at start). Cad: values below, from the CAD parts.")]
    public MassModel massModel = MassModel.Simplified;
    [Tooltip("Simplified model: distance from the center of buoyancy down to the center of mass (BG) with the moving mass at the tube center [m]. Larger = the robot rights itself more strongly in roll and pitch.")]
    public float centerOfMassBelowBuoyancy = 0.010f;
    [Tooltip("Simplified model: added inertia of the water in pitch and yaw [kg·m²] (slender cylinder, Docs/RobotFish_CAD_Report.md).")]
    public float waterAddedInertia = 0.0507f;
    [Tooltip("Center of mass of the structure, local axes [m]. Cad model: from the CAD report. Simplified model: computed at start.")]
    public Vector3 structureCenterOfMass = new Vector3(0.0237f, -0.0049f, 0f);
    [Tooltip("Principal moments of inertia of the structure about its own center of mass, local axes x (roll), y (yaw), z (pitch), including the added inertia of the water [kg·m²]. Cad model: from the CAD report. Simplified model: computed at start.")]
    public Vector3 structureInertia = new Vector3(0.0044f, 0.1322f, 0.1324f);

    // ------------------------------------------------------------------ hull geometry (displaced volume)
    [Header("Hull geometry (CAD)")]
    [Tooltip("Outer radius of the tube [m].")]
    public float tubeRadius = 0.055f;
    [Tooltip("Tube length [m], centered on the origin.")]
    public float tubeLength = 0.400f;
    [Tooltip("Radius and thickness of the cap discs outside each tube end [m].")]
    public float capRadius = 0.0577f;
    public float capThickness = 0.008f;
    [Tooltip("Radius of the front dome (hemisphere) [m].")]
    public float domeRadius = 0.0571f;
    [Tooltip("Parts outside the hull that also displace water (center in local axes [m], volume [m³]).")]
    public List<VolumeElement> externalVolumes = new List<VolumeElement>();
    [Tooltip("Spacing of the buoyancy points inside the hull [m].")]
    public float buoyancyPointSpacing = 0.01f;

    // ------------------------------------------------------------------ hydrodynamics
    [Header("Hull drag")]
    [Tooltip("Drag coefficient along the hull, on the frontal area (includes the tail drive).")]
    public float axialDragCoefficient = 0.6f;
    [Tooltip("Drag coefficient across the hull (cylinder in crossflow).")]
    public float crossflowDragCoefficient = 1.1f;
    [Tooltip("Number of slices of the hull for the crossflow drag.")]
    public int dragSlices = 12;
    [Tooltip("Projected areas of the tail drive (servo + support): seen from the side and from above [m²].")]
    public float tailDriveSideArea = 0.007f;
    public float tailDriveTopArea = 0.004f;
    [Tooltip("Center of the tail drive, local axes [m].")]
    public Vector3 tailDriveCenter = new Vector3(0.30f, -0.03f, 0f);
    [Tooltip("Small linear damping that keeps the robot from drifting forever at very low speed [N·s/m].")]
    public float linearDamping = 0.1f;
    [Tooltip("Small rotational damping (the hull drag gives almost none in roll) [N·m·s].")]
    public float angularDamping = 0.05f;

    // ------------------------------------------------------------------ fins
    [Header("Tail fin (moved by the servo)")]
    [Tooltip("Vertical axis of the tail servo, local axes [m].")]
    public Vector3 tailHinge = new Vector3(0.325f, 0.0062f, 0f);
    [Tooltip("Distance from the servo axis to the center of pressure of the fin (¼ chord) [m] (SimpleThrust model).")]
    public float tailPressureDistance = 0.104f;
    [Tooltip("Height of the center of the fin [m, local Y].")]
    public float tailFinHeight = -0.017f;
    public FinProperties tailFin = new FinProperties { area = 0.0192f, liftSlope = 1.2f, stallAngle = 25f };
    [Tooltip("Leading and trailing edges of the fin, distance behind the servo axis [m], and fin height (span) [m] (CAD: 160 × 120 mm plate).")]
    public float tailLeadingEdge = 0.064f;
    public float tailTrailingEdge = 0.224f;
    public float tailFinSpan = 0.120f;
    [Tooltip("Mechanical limit of the fin angle [deg] (±60°, team).")]
    public float maxTailAngle = 60f;
    [Tooltip("Fin angle at full rudder command [deg]: fixed angle (SimpleThrust), bias of the flapping (TailFlapping).")]
    public float rudderAngle = 30f;
    [Tooltip("Servo speed [deg/s] and torque [N·m] (Hitec D955TW at 7.4 V: 0.12 s/60°, 29 kgf·cm).")]
    public float tailServoSpeed = 500f;
    public float tailServoTorque = 2.84f;
    [Tooltip("Position gain of the servo [1/s]: speed command per degree of error (estimate, sets how closely the servo follows).")]
    public float tailServoGain = 40f;
    [Tooltip("Inertia of the moving tail parts (hub, arm, fin) about the servo axis, without the water [kg·m²] (estimate).")]
    public float tailFinInertia = 0.001f;
    [Tooltip("Visual of the fin, rotated about its local Y axis (optional).")]
    public Transform tailFinPivot;

    [Header("Dorsal fin (fixed)")]
    [Tooltip("Center of pressure of the dorsal fin, local axes [m].")]
    public Vector3 dorsalFinCenter = new Vector3(0.170f, 0.0853f, 0f);
    public FinProperties dorsalFin = new FinProperties { area = 0.0042f, liftSlope = 1.2f, stallAngle = 25f };

    // ------------------------------------------------------------------ moving mass
    [Header("Moving mass (pitch)")]
    [Tooltip("Weight that slides along the tube axis [kg]. Adjustable on the real robot; set to the weight that makes the robot neutral (0.714 kg with a 4 kg structure).")]
    public float movingMass = 0.714f;
    [Tooltip("Travel from the tube center to each end [m] (tube length minus 5 cm at each end: ±0.15 m).")]
    public float movingMassTravel = 0.15f;
    [Tooltip("Speed of the moving mass [m/s] (estimate: the actuator is not known).")]
    public float movingMassSpeed = 0.05f;
    [Tooltip("Position of the moving mass for a pitch command of 0 [m, + = forward].")]
    public float movingMassRestPosition = 0f;
    [Tooltip("At start, sets the rest position so that the robot rests level when submerged (moving mass right under the center of buoyancy), as an operator would do. Clamped to the travel.")]
    public bool levelAtRest = true;

    // ------------------------------------------------------------------ propulsion
    public enum PropulsionModel { TailFlapping, SimpleThrust }

    [Header("Propulsion")]
    [Tooltip("TailFlapping: the flapping tail fin swims the robot (real robot). SimpleThrust: fixed rudder + forward force (tests).")]
    public PropulsionModel propulsion = PropulsionModel.TailFlapping;

    [Header("Tail flapping")]
    [Tooltip("Flapping frequency at full tail_frequency command [Hz].")]
    public float maxTailFrequency = 3f;
    [Tooltip("Flapping used by the thrust command (Space key, /cmd/thrust): frequency [Hz] and amplitude at full command [deg].")]
    public float cruiseFrequency = 1.5f;
    public float cruiseAmplitude = 30f;
    [Tooltip("Added mass of the fin as a fraction of the 2D value ρ·π·span²/4 per unit chord (3D effects of the low aspect ratio fin, estimate).")]
    public float addedMassCoefficient = 0.7f;
    [Tooltip("Drag coefficient of the fin moving across its plate (flat plate).")]
    public float finCrossflowDrag = 1.2f;
    [Tooltip("Adds the water carried by the fin to the yaw inertia of the robot (off: see FinAddedYawInertia).")]
    public bool finAddedYawInertia = false;
    [Tooltip("Number of chordwise strips of the fin, and of rows over its height (the rows see the roll of the robot).")]
    public int tailFinStrips = 8;
    public int tailFinRows = 3;

    [Header("Simple thrust (SimpleThrust model only)")]
    [Tooltip("Forward force at full thrust command [N]; 0.3 N gives about 0.3 m/s.")]
    public float temporaryThrust = 0.3f;

    // ------------------------------------------------------------------ test ballast

    [Header("Test ballast (SIMULATION ONLY, the real robot has none)")]
    [Tooltip("Largest change of buoyancy the test ballast can make, as a fraction of the displaced volume.")]
    public float ballastRange = 0.25f;
    [Tooltip("Rate of change of the test ballast [fraction of the volume per second].")]
    public float ballastRate = 0.125f;

    // ------------------------------------------------------------------ commands
    [Header("Actuator commands (normalized to [-1, 1])")]
    [Tooltip("When on, the commands come from another component (e.g. ROS) instead of the keyboard.")]
    public bool externalControl = false;
    [Tooltip("Swim forward (Space). TailFlapping: flapping at cruiseFrequency with thrust × cruiseAmplitude (negative = 0, a fish cannot swim backward). SimpleThrust: forward force.")]
    [Range(-1f, 1f)] public float thrustCommand = 0f;
    [Tooltip("Turn. Fin bias (TailFlapping) or fin angle (SimpleThrust) as a fraction of rudderAngle. Positive = turn right (D).")]
    [Range(-1f, 1f)] public float rudderCommand = 0f;
    [Tooltip("TailFlapping, direct tail commands (used instead of thrust/rudder when any of them is not 0): frequency as a fraction of maxTailFrequency, amplitude and bias as fractions of maxTailAngle.")]
    [Range(0f, 1f)] public float tailFrequencyCommand = 0f;
    [Range(0f, 1f)] public float tailAmplitudeCommand = 0f;
    [Range(-1f, 1f)] public float tailBiasCommand = 0f;
    [Tooltip("Moving mass target: 0 = rest position, +1 = front end (nose down, W), −1 = back end (nose up, S).")]
    [Range(-1f, 1f)] public float pitchCommand = 0f;
    [Tooltip("SIMULATION ONLY. Test ballast pump. Positive = fill, heavier (Q).")]
    [Range(-1f, 1f)] public float ballastCommand = 0f;

    // ------------------------------------------------------------------ debug
    [Header("Debug (read-only)")]
    public float mass;                                // structure + moving mass [kg]
    public float bg;                                  // center of mass below the center of buoyancy [m]
    public float buoyancyPercent;                     // (water pushed up / weight − 1) × 100: + = floats
    public float displacedVolume;                     // sum of the buoyancy points [m³]
    public float submergedFraction;                   // part of the volume under water
    public float buoyancyForce;                       // [N]
    public float forwardSpeed;                        // [m/s]
    public float finAngle;                            // current tail fin angle [deg], + = turns right
    public float finTarget;                           // angle asked to the servo [deg]
    public float tailFrequency;                       // flapping actually commanded: frequency [Hz],
    public float tailAmplitude;                       // amplitude [deg]
    public float tailBias;                            // and bias [deg]
    public float tailThrust;                          // forward force of the tail, averaged over about 1 s [N]
    public float tailHingeMoment;                     // largest moment of the water on the fin about the servo axis, last ~1 s [N·m]
    public float strouhal;                            // f · (trailing edge peak-to-peak) / speed (fish: 0.2–0.4)
    public float movingMassPosition;                  // position along the tube axis [m], + = forward
    public float ballastAdjust;                       // test ballast [fraction of the volume], + = heavier
    public Vector3 centerOfBuoyancy;                  // local axes [m], with the robot fully submerged

    [System.Serializable]
    public struct VolumeElement
    {
        public string name;
        public Vector3 center;                        // local axes [m]
        public float volume;                          // [m³]
    }

    [System.Serializable]
    public struct FinProperties
    {
        public float area;                            // planform area of one face [m²]
        public float liftSlope;                       // normal-force slope at small angles [1/rad]
        public float stallAngle;                      // angle beyond which the fin behaves as a flat plate [deg]
    }

    private Rigidbody rb;
    private Vector3[] buoyancyPoints;                 // local positions
    private float[] buoyancyVolumes;                  // volume of each point [m³]
    private float[] buoyancySmoothing;                // height over which each point goes from dry to wet [m]
    private Vector3[] sliceCenters;                   // hull slices for the crossflow drag (local)
    private float[] sliceAreas;                       // diameter × length of each slice [m²]
    private float frontalArea;                        // [m²]
    private float[] stripRadii;                       // tail fin strips: distance from the servo axis [m]
    private float stripLength;                        // chordwise length of one strip [m]
    private float finMassPerLength;                   // added mass of the fin per unit chord [kg/m]
    private float tailAddedInertia;                   // added inertia of the fin about the servo axis [kg·m²]

    // Builds the buoyancy points and the drag slices, sets the mass properties
    void Start()
    {
        rb = GetComponent<Rigidbody>();
        if (basin == null) basin = FindAnyObjectByType<TestBasin>();
        rb.linearDamping = 0f;                        // the water drag is computed here
        rb.angularDamping = 0f;
        BuildBuoyancyPoints();
        BuildDragSlices();
        BuildTailStrips();
        if (massModel == MassModel.Simplified) SetSimplifiedMassModel();
        mass = structureMass + movingMass;
        buoyancyPercent = (WaterDensity * displacedVolume / mass - 1f) * 100f;
        if (levelAtRest && movingMass > 1e-4f)        // CoM under the CoB: structure·x_s + moving·x_m = mass·x_B
        {
            float x = (mass * centerOfBuoyancy.x - structureMass * structureCenterOfMass.x) / movingMass;
            movingMassRestPosition = Mathf.Clamp(-x, -movingMassTravel, movingMassTravel);   // forward = −X
        }
        movingMassPosition = movingMassRestPosition;
        rb.automaticInertiaTensor = false;
        rb.automaticCenterOfMass = false;
        rb.inertiaTensorRotation = Quaternion.identity;
        UpdateMassProperties();
    }

    // Simplified mass model: the structure is balanced so that, with the moving mass at the tube center, the center
    // of mass of the whole robot is right under the center of buoyancy, BG below it:
    //   structure·G_s + moving·(0, 0, 0) = total·(B − BG·up)  →  G_s = total·(B − BG·up) / structure.
    // Inertia of the structure: uniform solid cylinder of the hull size (tube radius, dome tip to rear cap),
    //   roll = ½·m·r², pitch = yaw = m·(3·r² + L²)/12, plus the added inertia of the water in pitch and yaw.
    void SetSimplifiedMassModel()
    {
        float total = structureMass + movingMass;
        Vector3 target = centerOfBuoyancy + Vector3.down * centerOfMassBelowBuoyancy;
        target.z = 0f;                                                     // laterally centered
        structureCenterOfMass = total * target / structureMass;
        float r = tubeRadius;
        float length = domeRadius + 2f * capThickness + tubeLength;       // dome tip to rear cap
        float across = structureMass * (3f * r * r + length * length) / 12f;
        structureInertia = new Vector3(0.5f * structureMass * r * r, across + waterAddedInertia, across + waterAddedInertia);
    }

    // Mass, center of mass and inertia of structure + moving mass (the moving mass is on the tube axis)
    void UpdateMassProperties()
    {
        mass = structureMass + movingMass;
        rb.mass = mass;
        Vector3 movingPoint = Vector3.left * movingMassPosition;                      // forward = −X
        Vector3 com = (structureMass * structureCenterOfMass + movingMass * movingPoint) / mass;
        rb.centerOfMass = com;
        bg = centerOfBuoyancy.y - com.y;
        // parallel-axis theorem: each part's inertia about the common center of mass (diagonal terms)
        Vector3 inertia = structureInertia + ParallelAxis(structureMass, structureCenterOfMass - com) + ParallelAxis(movingMass, movingPoint - com);
        if (propulsion == PropulsionModel.TailFlapping && finAddedYawInertia) inertia.y += FinAddedYawInertia(com);
        rb.inertiaTensor = inertia;
    }

    // Water carried by the tail fin when the robot yaws (the fin, far behind the center of mass, moves across
    // its plate). It is part of the inertia instead of a force computed from the robot's own acceleration,
    // which would be unstable (this added inertia is larger than the inertia of the robot itself).
    // Off by default (finAddedYawInertia): with it, the model dives while swimming. The larger yaw inertia changes the
    // phase between the roll oscillation (the side force of the fin acts below the center of mass) and the side
    // force, which then gets a steady vertical component at the tail. This depends on roll dynamics that the model
    // does not represent well (roll damping and added inertia of the fins), so the simpler, stable option is
    // the default; the price is a yaw oscillation somewhat larger than with the added inertia.
    float FinAddedYawInertia(Vector3 com)
    {
        float sum = 0f;
        foreach (float r in stripRadii)
        {
            float dx = tailHinge.x + r - com.x, dz = tailHinge.z - com.z;
            sum += finMassPerLength * stripLength * (dx * dx + dz * dz);
        }
        return sum;
    }

    static Vector3 ParallelAxis(float m, Vector3 d) =>
        m * new Vector3(d.y * d.y + d.z * d.z, d.x * d.x + d.z * d.z, d.x * d.x + d.y * d.y);

    void FixedUpdate()
    {
        float dt = Time.fixedDeltaTime;
        if (!externalControl) ReadKeyboard();
        UpdateActuators(dt);
        ApplyBuoyancy();
        ApplyHullDrag();
        if (propulsion == PropulsionModel.TailFlapping) ApplyFlappingTail(dt);
        else
        {
            ApplyFin(TailFinFrame(), tailFin);
            ApplyTemporaryThrust();
        }
        ApplyFin(new FinFrame { center = dorsalFinCenter, normal = Vector3.forward, swingSpeed = 0f }, dorsalFin);
    }

    // ================================================================== 1. actuators
    // Keyboard → commands (same keys as the original AUV model)
    void ReadKeyboard()
    {
        thrustCommand = rudderCommand = pitchCommand = ballastCommand = 0f;
        tailFrequencyCommand = tailAmplitudeCommand = tailBiasCommand = 0f;
        var k = Keyboard.current;
        if (k == null) return;
        if (k.spaceKey.isPressed) thrustCommand = 1f;
        if (k.dKey.isPressed || k.rightArrowKey.isPressed) rudderCommand = 1f;
        if (k.aKey.isPressed || k.leftArrowKey.isPressed) rudderCommand = -1f;
        if (k.wKey.isPressed || k.upArrowKey.isPressed) pitchCommand = 1f;
        if (k.sKey.isPressed || k.downArrowKey.isPressed) pitchCommand = -1f;
        if (k.qKey.isPressed || k.leftShiftKey.isPressed) ballastCommand += 1f;
        if (k.eKey.isPressed || k.leftCtrlKey.isPressed) ballastCommand -= 1f;
    }

    private float finRate;                            // fin angular speed [rad/s], used for the swing velocity
    private float finAcceleration;                    // fin angular acceleration [rad/s²]
    private float tailPhase;                          // phase of the flapping oscillator [rad]

    // The servos move toward their targets at a limited speed
    void UpdateActuators(float dt)
    {
        UpdateTail(dt);
        if (tailFinPivot != null) tailFinPivot.localRotation = Quaternion.Euler(0f, -finAngle, 0f); // + angle: trailing edge to the right (+Z)

        // moving mass: 0 = rest position, +1 = front end, −1 = back end; it moves at a limited speed
        float cmd = Mathf.Clamp(pitchCommand, -1f, 1f);
        float rest = movingMassRestPosition;
        float target = cmd >= 0f ? rest + cmd * (movingMassTravel - rest) : rest + cmd * (rest + movingMassTravel);
        movingMassPosition = Mathf.MoveTowards(movingMassPosition, target, movingMassSpeed * dt);
        UpdateMassProperties();

        // test ballast (simulation only)
        ballastAdjust = Mathf.Clamp(ballastAdjust + Mathf.Clamp(ballastCommand, -1f, 1f) * ballastRate * dt, -ballastRange, ballastRange);
    }

    // Tail: commands → angle asked to the servo → servo motion.
    void UpdateTail(float dt)
    {
        if (propulsion == PropulsionModel.SimpleThrust)
        {
            // fixed rudder: the servo goes to the commanded angle at its rated speed
            tailFrequency = tailAmplitude = 0f;
            tailBias = finTarget = Mathf.Clamp(rudderCommand, -1f, 1f) * rudderAngle;
            float previous = finAngle;
            finAngle = Mathf.MoveTowards(finAngle, finTarget, tailServoSpeed * dt);
            finRate = (finAngle - previous) * Mathf.Deg2Rad / dt;
            finAcceleration = 0f;
            return;
        }

        // oscillator: direct tail commands if any is set, otherwise the thrust/rudder shortcuts
        if (tailFrequencyCommand != 0f || tailAmplitudeCommand != 0f || tailBiasCommand != 0f)
        {
            tailFrequency = Mathf.Clamp01(tailFrequencyCommand) * maxTailFrequency;
            tailAmplitude = Mathf.Clamp01(tailAmplitudeCommand) * maxTailAngle;
            tailBias = Mathf.Clamp(tailBiasCommand, -1f, 1f) * maxTailAngle;
        }
        else
        {
            float thrust = Mathf.Clamp01(thrustCommand);                  // no backward swimming
            tailFrequency = thrust > 0f ? cruiseFrequency : 0f;
            tailAmplitude = thrust * cruiseAmplitude;
            tailBias = Mathf.Clamp(rudderCommand, -1f, 1f) * rudderAngle;
        }
        // the phase is integrated, so a change of frequency does not make the fin jump
        tailPhase = Mathf.Repeat(tailPhase + 2f * Mathf.PI * tailFrequency * dt, 2f * Mathf.PI);
        finTarget = Mathf.Clamp(tailBias + tailAmplitude * Mathf.Sin(tailPhase), -maxTailAngle, maxTailAngle);
        ServoStep(dt);
    }

    // Servo: position loop limited by the rated speed and by the torque. The torque has to accelerate the fin
    // and the water it carries (added inertia), so the servo cannot follow a fast and wide oscillation: the
    // fin then lags and its amplitude drops, as on the real robot. The speed asked to the servo is the smallest of
    //   gain × error            (proportional response),
    //   √(2 · a_max · |error|)  (the fin can still stop at the target with the available acceleration),
    //   tailServoSpeed          (rated speed),
    // and the actual speed moves toward it at the largest acceleration a_max = torque / inertia.
    void ServoStep(float dt)
    {
        float maxAcceleration = tailServoTorque / (tailFinInertia + tailAddedInertia) * Mathf.Rad2Deg;   // [deg/s²]
        float error = finTarget - finAngle;                                                            // [deg]
        float wanted = Mathf.Sign(error) * Mathf.Min(tailServoGain * Mathf.Abs(error),
                                                     Mathf.Sqrt(2f * maxAcceleration * Mathf.Abs(error)),
                                                     tailServoSpeed);
        float rate = finRate * Mathf.Rad2Deg;                                                          // [deg/s]
        float newRate = Mathf.MoveTowards(rate, wanted, maxAcceleration * dt);
        finAngle += newRate * dt;
        if (Mathf.Abs(finAngle) > maxTailAngle)                                                        // mechanical stop
        {
            finAngle = Mathf.Clamp(finAngle, -maxTailAngle, maxTailAngle);
            newRate = 0f;
        }
        finAcceleration = (newRate - rate) * Mathf.Deg2Rad / dt;
        finRate = newRate * Mathf.Deg2Rad;
    }

    void ApplyTemporaryThrust()
    {
        float thrust = Mathf.Clamp(thrustCommand, -1f, 1f) * temporaryThrust * submergedFraction;
        if (Mathf.Abs(thrust) > 1e-5f)
            rb.AddForceAtPosition(transform.TransformDirection(Vector3.left) * thrust,
                                  transform.TransformPoint(new Vector3(tailHinge.x, tailFinHeight, 0f)));
    }

    // ================================================================== 3. buoyancy
    // Fills the displaced volume with points: tube (cylinder), cap discs, dome (hemisphere toward −X),
    // plus one point per external part. Each point carries its share of the volume.
    void BuildBuoyancyPoints()
    {
        var points = new List<Vector3>();
        var volumes = new List<float>();
        var smoothing = new List<float>();
        float h = buoyancyPointSpacing;
        float cell = h * h * h;
        float front = -tubeLength / 2f - capThickness;            // front face of the front cap
        float back = tubeLength / 2f + capThickness;              // back face of the rear cap
        int nr = Mathf.CeilToInt(capRadius / h);
        for (float x = front - domeRadius + h / 2f; x < back; x += h)
        {
            for (int iy = -nr; iy <= nr; iy++)
            for (int iz = -nr; iz <= nr; iz++)
            {
                float y = iy * h, z = iz * h, r2 = y * y + z * z;
                bool inside;
                if (x < front) { float dx = x - front; inside = dx * dx + r2 <= domeRadius * domeRadius; }   // dome
                else if (x < -tubeLength / 2f || x > tubeLength / 2f) inside = r2 <= capRadius * capRadius; // cap discs
                else inside = r2 <= tubeRadius * tubeRadius;                                                   // tube
                if (!inside) continue;
                points.Add(new Vector3(x, y, z));
                volumes.Add(cell);
                smoothing.Add(h);
            }
        }
        // The grid does not match the exact volume of round shapes: rescale to the exact hull volume
        float exact = Mathf.PI * tubeRadius * tubeRadius * tubeLength
                    + 2f * Mathf.PI * capRadius * capRadius * capThickness
                    + 2f / 3f * Mathf.PI * domeRadius * domeRadius * domeRadius;
        float gridVolume = 0f;
        foreach (float v in volumes) gridVolume += v;
        for (int i = 0; i < volumes.Count; i++) volumes[i] *= exact / gridVolume;
        foreach (var e in externalVolumes)
        {
            points.Add(e.center);
            volumes.Add(e.volume);
            smoothing.Add(Mathf.Max(Mathf.Pow(e.volume, 1f / 3f), h));
        }
        buoyancyPoints = points.ToArray();
        buoyancyVolumes = volumes.ToArray();
        buoyancySmoothing = smoothing.ToArray();
        displacedVolume = 0f;
        centerOfBuoyancy = Vector3.zero;
        for (int i = 0; i < buoyancyPoints.Length; i++)
        {
            displacedVolume += buoyancyVolumes[i];
            centerOfBuoyancy += buoyancyVolumes[i] * buoyancyPoints[i];
        }
        centerOfBuoyancy /= displacedVolume;
    }

    // Archimedes on each point: F = ρ·g·V·(wet fraction). The wet fraction goes from 0 to 1 over one
    // point spacing around the surface, so the robot emerges smoothly. Forces are summed into one force
    // and one torque about the center of mass (cheaper than one AddForce per point).
    void ApplyBuoyancy()
    {
        float g = -Physics.gravity.y;
        float surface = WaterLevel;
        Vector3 com = rb.worldCenterOfMass;
        Vector3 force = Vector3.zero, torque = Vector3.zero;
        float wetVolume = 0f;
        float scale = 1f - ballastAdjust;                                     // test ballast changes the buoyancy
        for (int i = 0; i < buoyancyPoints.Length; i++)
        {
            Vector3 p = transform.TransformPoint(buoyancyPoints[i]);
            float wet = Mathf.Clamp01((surface - p.y) / buoyancySmoothing[i] + 0.5f);
            if (wet <= 0f) continue;
            float v = buoyancyVolumes[i] * wet;
            wetVolume += v;
            Vector3 f = Vector3.up * (WaterDensity * g * v * scale);
            force += f;
            torque += Vector3.Cross(p - com, f);
        }
        submergedFraction = wetVolume / displacedVolume;
        buoyancyForce = force.y;
        rb.AddForce(force);
        rb.AddTorque(torque);
    }

    float WaterLevel => basin != null ? basin.WaterSurfaceY : fallbackWaterLevel;

    // ================================================================== 4. hull drag
    // Cuts the hull (dome + tube + caps) into slices along X; each slice has a projected area
    // (local diameter × slice length) for the crossflow drag.
    void BuildDragSlices()
    {
        float front = -tubeLength / 2f - capThickness - domeRadius;
        float back = tubeLength / 2f + capThickness;
        float len = (back - front) / dragSlices;
        sliceCenters = new Vector3[dragSlices];
        sliceAreas = new float[dragSlices];
        float domeBase = -tubeLength / 2f - capThickness;
        for (int i = 0; i < dragSlices; i++)
        {
            float x = front + (i + 0.5f) * len;
            float radius = x < domeBase ? Mathf.Sqrt(Mathf.Max(0f, domeRadius * domeRadius - (x - domeBase) * (x - domeBase))) : tubeRadius;
            sliceCenters[i] = new Vector3(x, 0f, 0f);
            sliceAreas[i] = 2f * radius * len;
        }
        frontalArea = Mathf.PI * tubeRadius * tubeRadius;
    }

    // Quadratic drag F = −½·ρ·C·A·|v|·v:
    //   - along the hull: one force with the frontal area and the axial coefficient;
    //   - across the hull: one force per slice, with the slice's own sideways/vertical velocity, so a
    //     rotating hull is braked too (the slices far from the center move faster);
    //   - the tail drive (servo + support) adds its own crossflow drag;
    //   - small linear damping (translation and rotation) for very low speeds.
    // Every term is scaled by how much of it is under water.
    void ApplyHullDrag()
    {
        float surface = WaterLevel;
        float q = 0.5f * WaterDensity;

        Vector3 vCenter = transform.InverseTransformDirection(rb.GetPointVelocity(transform.position));
        forwardSpeed = -vCenter.x;
        float axial = -q * axialDragCoefficient * frontalArea * vCenter.x * Mathf.Abs(vCenter.x) * submergedFraction;
        rb.AddForceAtPosition(transform.TransformDirection(new Vector3(axial, 0f, 0f)), transform.TransformPoint(new Vector3(0f, centerOfBuoyancy.y, 0f)));

        for (int i = 0; i < sliceCenters.Length; i++)
            AddCrossflowDrag(sliceCenters[i], sliceAreas[i], sliceAreas[i], 2f * tubeRadius, surface, q);
        AddCrossflowDrag(tailDriveCenter, tailDriveSideArea, tailDriveTopArea, 0.08f, surface, q);

        rb.AddForce(-linearDamping * submergedFraction * rb.linearVelocity);
        rb.AddTorque(-angularDamping * submergedFraction * rb.angularVelocity);
    }

    // Crossflow drag of one element: sideways (local Z) and vertical (local Y) velocity components,
    // with the projected area seen from the side and from above.
    void AddCrossflowDrag(Vector3 localCenter, float sideArea, float topArea, float height, float surface, float q)
    {
        Vector3 p = transform.TransformPoint(localCenter);
        float wet = Mathf.Clamp01((surface - p.y) / height + 0.5f);
        if (wet <= 0f) return;
        Vector3 v = transform.InverseTransformDirection(rb.GetPointVelocity(p));
        float cross = Mathf.Sqrt(v.y * v.y + v.z * v.z);
        var f = new Vector3(0f,
                            -q * crossflowDragCoefficient * topArea * cross * v.y,
                            -q * crossflowDragCoefficient * sideArea * cross * v.z) * wet;
        rb.AddForceAtPosition(transform.TransformDirection(f), p);
    }

    // ================================================================== 5. fins
    struct FinFrame
    {
        public Vector3 center;                        // center of pressure, local axes
        public Vector3 normal;                        // normal of the fin plate, local axes
        public float swingSpeed;                      // speed of the center of pressure due to the servo motion [m/s], along the normal
    }

    // Tail fin frame: the chord turns about the vertical servo axis by the fin angle.
    // A positive angle moves the trailing edge to the right (+Z).
    FinFrame TailFinFrame()
    {
        float a = finAngle * Mathf.Deg2Rad;
        var chord = new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a));               // from the servo axis toward the trailing edge
        var normal = new Vector3(-Mathf.Sin(a), 0f, Mathf.Cos(a));
        Vector3 center = new Vector3(tailHinge.x, tailFinHeight, tailHinge.z) + chord * tailPressureDistance;
        return new FinFrame { center = center, normal = normal, swingSpeed = finRate * tailPressureDistance };
    }

    // Quasi-steady fin force: a flat plate moving through the water feels a force along its normal,
    //   F = −n · ½·ρ·A·|v|²·C_N(α),   α = angle between the velocity and the plate (sin α = v·n / |v|),
    //   C_N(α) = liftSlope·α below the stall angle (lift of a small fin), 1.2·sin α beyond (flat plate).
    // The force always opposes the velocity component across the plate. With the fin deflected while the
    // robot moves forward, it pushes the stern sideways (steering); with the fin centered, it resists any
    // sideways slide of the stern (passive stability, like the feathers of an arrow).
    void ApplyFin(FinFrame frame, FinProperties fin)
    {
        Vector3 p = transform.TransformPoint(frame.center);
        float wet = Mathf.Clamp01((WaterLevel - p.y) / 0.06f + 0.5f);
        if (wet <= 0f) return;
        Vector3 v = transform.InverseTransformDirection(rb.GetPointVelocity(p)) + frame.normal * frame.swingSpeed;
        float speed = v.magnitude;
        if (speed < 1e-4f) return;
        float alpha = Mathf.Asin(Mathf.Clamp(Vector3.Dot(v, frame.normal) / speed, -1f, 1f));
        float stall = fin.stallAngle * Mathf.Deg2Rad;
        float cn = Mathf.Abs(alpha) < stall ? fin.liftSlope * alpha : 1.2f * Mathf.Sin(alpha);
        Vector3 f = -frame.normal * (0.5f * WaterDensity * fin.area * speed * speed * cn * wet);
        rb.AddForceAtPosition(transform.TransformDirection(f), p);
    }

    // ================================================================== 6. flapping tail
    // The fin (rigid plate, chord from tailLeadingEdge to tailTrailingEdge behind the servo axis, height
    // tailFinSpan) is cut into chordwise strips and into rows over its height. Each element has a normal velocity
    // w through the water (robot motion + fin swing), and the water it pushes behaves like an added mass
    // m' = C·ρ·π·span²/4 per unit chord (flat plate moving across itself), shared equally between the rows.
    // The rows matter for the roll: when the robot rolls, the top and the bottom of the fin move sideways in
    // opposite directions and the water resists it (roll damping). Forces of the water on the fin, after Lighthill's elongated-body theory
    // (reactive part) with a resistive drag:
    //   1. reactive, along the fin: −d/dt(m'·w·n) for each strip, keeping only the acceleration given by the
    //      servo (the part due to the robot's own acceleration is the added inertia of UpdateMassProperties);
    //   2. reactive, trailing edge (one point per row): the water set in motion leaves the fin there and forms the wake; the
    //      momentum it takes away pushes the robot by F = m'·(w·u·n − ½·w²·τ) (u, w: velocity of the trailing
    //      edge along the fin τ (toward the trailing edge) and across it n). This term gives the thrust: with
    //      the robot at rest it is −½·m'·w²·τ, forward. With the fin held deflected while the robot moves, it
    //      gives a side force (steering) and a drag;
    //   3. resistive: crossflow drag of each element, −½·ρ·C_D·(span/rows)·Δr·|w|·w·n.
    // These replace the quasi-steady fin force (which, for a flapping fin, gives drag instead of thrust).
    void BuildTailStrips()
    {
        int n = Mathf.Max(1, tailFinStrips);
        stripLength = (tailTrailingEdge - tailLeadingEdge) / n;
        stripRadii = new float[n];
        finMassPerLength = addedMassCoefficient * WaterDensity * Mathf.PI * tailFinSpan * tailFinSpan / 4f;
        tailAddedInertia = 0f;
        for (int i = 0; i < n; i++)
        {
            stripRadii[i] = tailLeadingEdge + (i + 0.5f) * stripLength;
            tailAddedInertia += finMassPerLength * stripLength * stripRadii[i] * stripRadii[i];
        }
    }

    void ApplyFlappingTail(float dt)
    {
        float a = finAngle * Mathf.Deg2Rad;
        var tangent = new Vector3(Mathf.Cos(a), 0f, Mathf.Sin(a));             // along the chord, toward the trailing edge
        var normal = new Vector3(-Mathf.Sin(a), 0f, Mathf.Cos(a));             // across the fin (+Z at 0°)
        int rows = Mathf.Max(1, tailFinRows);
        float rowHeight = tailFinSpan / rows;
        float rowMass = finMassPerLength / rows;                                // added mass per unit chord of one row [kg/m]
        float forward = 0f, moment = 0f;                                       // forward force [N], moment about the servo axis [N·m]

        for (int j = 0; j < rows; j++)
        {
            var hinge = new Vector3(tailHinge.x, tailFinHeight - tailFinSpan / 2f + (j + 0.5f) * rowHeight, tailHinge.z);

            // 1 + 3: strips of this row
            foreach (float r in stripRadii)
            {
                float w = NormalVelocity(hinge + tangent * r, normal, r, rowHeight, out Vector3 p, out float wet, out _);
                if (wet <= 0f) continue;
                Vector3 f = -normal * (0.5f * WaterDensity * finCrossflowDrag * rowHeight * stripLength * Mathf.Abs(w) * w)
                          - rowMass * stripLength * (r * finAcceleration * normal - w * finRate * tangent);
                f *= wet;
                rb.AddForceAtPosition(transform.TransformDirection(f), p);
                forward -= f.x;                                                // forward = −X
                moment += r * Vector3.Dot(f, normal);
            }

            // 2: trailing edge of this row
            float wTe = NormalVelocity(hinge + tangent * tailTrailingEdge, normal, tailTrailingEdge, rowHeight, out Vector3 pTe, out float wetTe, out Vector3 vTe);
            if (wetTe > 0f)
            {
                float u = Vector3.Dot(vTe, tangent);
                Vector3 f = rowMass * (wTe * u * normal - 0.5f * wTe * wTe * tangent) * wetTe;
                rb.AddForceAtPosition(transform.TransformDirection(f), pTe);
                forward -= f.x;
                moment += tailTrailingEdge * Vector3.Dot(f, normal);
            }
        }

        // debug values
        tailThrust += (forward - tailThrust) * Mathf.Min(1f, dt / 1f);                     // ~1 s average
        tailHingeMoment = Mathf.Max(Mathf.Abs(moment), tailHingeMoment * (1f - dt));       // slowly decaying peak
        strouhal = forwardSpeed > 0.05f
            ? tailFrequency * 2f * tailTrailingEdge * Mathf.Sin(Mathf.Min(tailAmplitude, 90f) * Mathf.Deg2Rad) / forwardSpeed
            : 0f;
    }

    // Velocity across the fin of a point of the fin at distance r from the servo axis (local axes):
    // robot velocity at that point + swing of the fin. Also returns the world position, the wet fraction
    // and the full local velocity.
    float NormalVelocity(Vector3 local, Vector3 normal, float r, float height, out Vector3 world, out float wet, out Vector3 v)
    {
        world = transform.TransformPoint(local);
        wet = Mathf.Clamp01((WaterLevel - world.y) / height + 0.5f);
        v = transform.InverseTransformDirection(rb.GetPointVelocity(world)) + normal * (r * finRate);
        return Vector3.Dot(v, normal);
    }
}
